const QUESTION_BANK = [

  // ---------- Momentum and Impulse ----------
  { id: 'mom-01', topic: 'momentum', level: 1, q: 'A hornbill and a supply cart have equal momentum but travel in opposite directions along a vine bridge. What must a complete comparison include?', answers: ['Both magnitude and direction, because momentum is the vector product mv.', 'Only their speeds, because equal momentum makes direction irrelevant.', 'Only the forces driving them, because momentum is force multiplied by time.'], correct: 0 },
  { id: 'mom-02', topic: 'momentum', level: 1, q: 'A vine delivers a brief force that brings a swinging explorer to rest. Which interpretation links the interaction to the explorer’s motion?', answers: ['The vine’s impulse equals the explorer’s change in momentum.', 'The vine supplies the momentum the explorer possessed before stopping.', 'The stopping force alone is the impulse, regardless of how long it acts.'], correct: 0 },
  { id: 'mom-03', topic: 'momentum', level: 1, q: 'Jamnani records the force on a raft during a collision as a force–time graph. Which feature determines the raft’s momentum change?', answers: ['The area under the graph, because it is the impulse Δp.', 'The maximum height alone, because peak force equals impulse.', 'The final gradient, because acceleration is the area under a force–time graph.'], correct: 0 },
  { id: 'mom-04', topic: 'momentum', level: 2, q: 'Explain why landing on deep moss hurts less than landing on stone.', answers: ['The moss extends the collision time, so the same momentum change occurs with a smaller average force.', 'The moss reduces the momentum change by absorbing some of the momentum.', 'The moss destroys energy on contact, so less force reaches you.'], correct: 0 },
  { id: 'mom-05', topic: 'momentum', level: 2, q: 'A ball hits a wall and rebounds at the same speed. Why is the momentum change large?', answers: ['The initial and final momenta point in opposite directions, so the change is the sum of their magnitudes.', 'The wall adds momentum to the ball to send it back.', 'The speed doubles on impact, doubling the momentum.'], correct: 0 },
  { id: 'mom-06', topic: 'momentum', level: 2, q: 'Why can internal forces never change a system’s total momentum?', answers: ['They act in equal and opposite Newton’s-third-law pairs, which cancel for the system as a whole.', 'Internal forces are always weaker than external forces.', 'Internal forces only act while objects are touching.'], correct: 0 },
  { id: 'mom-07', topic: 'momentum', level: 2, q: 'Newton’s second law in momentum form says F_net = Δp/Δt. What follows when the net force is zero?', answers: ['Momentum stays constant — the object may still be moving, but its momentum cannot change.', 'The object must be stationary, since zero force means no motion.', 'Momentum steadily decreases to zero through friction.'], correct: 0 },
  { id: 'mom-08', topic: 'momentum', level: 2, q: 'A bamboo rover has a flexible front cage rather than a rigid one. Explain why this reduces the force on its passengers in a collision.', answers: ['The cage increases the stopping time, so the same momentum change requires a smaller average force.', 'The cage absorbs and destroys the passengers’ momentum before they decelerate.', 'The cage makes the passengers’ momentum change smaller even though their initial and final velocities are unchanged.'], correct: 0 },
  { id: 'mom-09', topic: 'momentum', level: 3, q: 'A firework shell explodes mid-flight. Discuss what happens to the centre of mass (ignore air resistance).', answers: ['It continues on the original projectile path — the explosion forces are internal, so only gravity moves the centre of mass.', 'It drops straight down, because the pieces lose their forward push at the moment of explosion.', 'It accelerates upward, since the explosion adds energy to the system.'], correct: 0 },
  { id: 'mom-10', topic: 'momentum', level: 3, q: 'Two temple stones collide on a level track: in one trial they rebound, while in another they lock together. Compare the conservation laws governing the two trials.', answers: ['Total momentum is conserved in both isolated trials; kinetic energy is conserved only in the elastic rebound, while locking transfers some to other forms.', 'Kinetic energy is conserved in both trials; locking changes only the momentum because the stones share one velocity.', 'Momentum is conserved only when the stones rebound, because lost kinetic energy must be replaced by lost momentum.'], correct: 0 },
  { id: 'mom-11', topic: 'momentum', level: 3, q: 'Two skaters stand at rest and push apart. Justify what happens to the system’s centre of mass.', answers: ['It stays where it is: the skaters gain equal and opposite momenta, so the total momentum — and the centre-of-mass motion — remains zero.', 'It moves with the heavier skater, who pushes harder and carries more momentum.', 'It drifts toward the faster skater, since speed matters more than mass here.'], correct: 0 },
  { id: 'mom-12', topic: 'momentum', level: 3, q: 'Why is total momentum conserved during a collision in an isolated system?', answers: ['With no net external force there is nothing that can change the total momentum — internal pairs cancel.', 'Because energy conservation forces the momentum to balance out as well.', 'Because the colliding masses are equal, their momenta cancel by symmetry.'], correct: 0 },

  // ---------- Energy and Work ----------
  { id: 'ene-01', topic: 'energy', level: 1, q: 'A porter carries a supply crate horizontally at constant height through the canopy. Why does the upward support force do no work on the crate?', answers: ['The force is perpendicular to the horizontal displacement, so Fd cos 90° = 0.', 'The support force is smaller than the crate’s weight, so it cannot transfer energy.', 'The crate moves too slowly for the support force to perform work.'], correct: 0 },
  { id: 'ene-02', topic: 'energy', level: 1, q: 'A falling jungle fruit loses gravitational potential energy and warms the ground when it lands. Which account is consistent with energy conservation?', answers: ['Energy is transferred among gravitational, kinetic, thermal and sound forms; it is not created or destroyed.', 'Kinetic energy is created during the fall and then disappears into the ground.', 'Friction destroys mechanical energy, so total energy decreases after impact.'], correct: 0 },
  { id: 'ene-03', topic: 'energy', level: 1, q: 'For a frictionless vine swing, which energies must be tracked to test whether its mechanical energy remains constant?', answers: ['Its kinetic and gravitational potential energies.', 'Its kinetic and thermal energies only.', 'Every energy form in the jungle, including chemical and sound energy.'], correct: 0 },
  { id: 'ene-04', topic: 'energy', level: 2, q: 'Explain why doubling an object’s speed quadruples its kinetic energy.', answers: ['Kinetic energy depends on v², so twice the speed gives four times the energy.', 'Doubling the speed doubles the mass effectively involved.', 'Speed enters the energy formula twice — once for distance, once for time.'], correct: 0 },
  { id: 'ene-05', topic: 'energy', level: 2, q: 'Why does the work formula include cos θ?', answers: ['Only the component of force along the displacement transfers energy; the perpendicular component does no work.', 'The angle corrects the force for the object’s weight.', 'cos θ converts force into power along the slope.'], correct: 0 },
  { id: 'ene-06', topic: 'energy', level: 2, q: 'A fruit falls from a branch, ignoring drag. Discuss its energy through the fall.', answers: ['Gravitational potential energy converts to kinetic energy, and the total mechanical energy stays constant.', 'Kinetic energy is created new at each moment, increasing the total.', 'Potential energy is destroyed on release and replaced by downward force.'], correct: 0 },
  { id: 'ene-07', topic: 'energy', level: 2, q: 'Why are energy methods preferred when forces vary or height changes?', answers: ['Energy conservation links the start and end states directly, without needing the force at every point along the way.', 'Because energy is conserved, no calculation is needed at all.', 'Forces do not act on objects that change height.'], correct: 0 },
  { id: 'ene-08', topic: 'energy', level: 2, q: 'An explorer holds a heavy relic motionless above a pressure plate. Explain the mechanical work done by the explorer’s upward force on the relic.', answers: ['It is zero because the relic has no displacement, despite the large force and the explorer’s biological energy use.', 'It is large because work increases whenever a force is maintained for a long time.', 'It equals the relic’s weight multiplied by the time it is held.'], correct: 0 },
  { id: 'ene-09', topic: 'energy', level: 3, q: 'A spring is stretched twice as far as before. Justify what happens to the stored elastic energy.', answers: ['It quadruples — elastic energy depends on the square of the extension.', 'It doubles, because energy scales with extension.', 'It stays the same, since the spring constant has not changed.'], correct: 0 },
  { id: 'ene-10', topic: 'energy', level: 3, q: 'A ball bounces on concrete but never returns to its drop height. Explain why.', answers: ['At each bounce some kinetic energy transfers to thermal and sound energy, so less remains as potential energy.', 'Gravity weakens each time the ball rises, capping its height.', 'The ball stores a fixed energy tax in the concrete on every impact.'], correct: 0 },
  { id: 'ene-11', topic: 'energy', level: 3, q: 'A slider descends a frictionless slide. Compare its energies at top and bottom.', answers: ['The potential energy lost (mgΔh) equals the kinetic energy gained — mechanical energy is conserved.', 'Kinetic energy at the bottom exceeds the potential energy lost, since speed adds extra.', 'Potential energy at the top exceeds kinetic energy at the bottom, because gravity resists the descent.'], correct: 0 },
  { id: 'ene-12', topic: 'energy', level: 3, q: 'Why is gravitational potential energy written as a change, mgΔh, rather than an absolute amount?', answers: ['Only differences between heights have physical meaning — the zero level is an arbitrary choice of reference.', 'Because g changes continuously with height in every problem.', 'Because mass varies slightly with position above the ground.'], correct: 0 },

  // ---------- Centre of Mass ----------
  { id: 'com-01', topic: 'com', level: 1, q: 'A strangely shaped idol tumbles through the air. Why is marking its centre of mass useful when analysing the overall motion?', answers: ['Its total mass can be treated as concentrated there for translational motion, even while the idol rotates.', 'It identifies the idol’s densest piece, which must follow a straight path.', 'It gives the geometric centre, which is fixed at the same point for every object.'], correct: 0 },
  { id: 'com-02', topic: 'com', level: 1, q: 'A uniform stone ring hangs around a temple opening. Where must its centre of mass lie, and what does this reveal?', answers: ['At the centre of the hole, showing that a centre of mass need not lie within the object’s material.', 'Within the stone band, because centre of mass must coincide with matter.', 'Nowhere, because hollow objects cannot have a defined centre of mass.'], correct: 0 },
  { id: 'com-03', topic: 'com', level: 1, q: 'A thrown jungle staff both travels across a clearing and spins. How should these motions be separated for analysis?', answers: ['As translation of its centre of mass plus rotation about the centre of mass.', 'As translation only, because rotation does not affect the motion of its parts.', 'As rotation only, because every point on the staff traces a circle.'], correct: 0 },
  { id: 'com-04', topic: 'com', level: 1, q: 'A leaning idol begins to topple when its support can no longer provide a balancing torque. Through which point should its weight be modelled as acting?', answers: ['Through its centre of mass.', 'Through its lowest point, because gravity always acts nearest the ground.', 'Through the edge of its base that remains in contact.'], correct: 0 },
  { id: 'com-05', topic: 'com', level: 2, q: 'Why is the centre of mass a mass-weighted average position?', answers: ['Heavier pieces pull the average toward their own side — each position counts in proportion to its mass.', 'Every part of an object contributes equally, regardless of mass.', 'The average is weighted by volume, so hollow objects have no centre of mass.'], correct: 0 },
  { id: 'com-06', topic: 'com', level: 2, q: 'If the net external force on a system is zero, the centre of mass…', answers: ['remains at rest or moves with constant velocity.', 'must remain at rest — motion is impossible without force.', 'accelerates uniformly in the direction of the largest internal force.'], correct: 0 },
  { id: 'com-07', topic: 'com', level: 2, q: 'Explain why internal forces cannot move a system’s centre of mass.', answers: ['Internal forces come in equal and opposite pairs, so their effects cancel when the whole system is considered.', 'Internal forces are absorbed by friction before they can act.', 'Internal forces act only on rotation, never on position.'], correct: 0 },
  { id: 'com-08', topic: 'com', level: 2, q: 'Monkeys scramble in different directions across a drifting raft. Use F_net,external = M_total a_COM to explain which motion can change the raft–monkey system’s centre-of-mass velocity.', answers: ['Only a net external force can accelerate the centre of mass; the monkeys’ internal forces can rearrange the system but cannot change its total momentum.', 'Every monkey must share the same acceleration because the equation contains only one a_COM.', 'The monkeys’ internal pushes must be added to the external force before the equation can be applied.'], correct: 0 },
  { id: 'com-09', topic: 'com', level: 3, q: 'A firework explodes at the top of its flight. Discuss the motion of the fragments and the centre of mass (ignore air resistance).', answers: ['The fragments fan apart, but the centre of mass keeps following the original projectile path, because the explosion forces are internal.', 'The fragments and the centre of mass both fall straight down from the explosion point.', 'The centre of mass gains upward velocity from the energy released in the blast.'], correct: 0 },
  { id: 'com-10', topic: 'com', level: 3, q: 'A rocket in deep space expels gas backward. Justify what happens to the centre of mass of the rocket-plus-gas system.', answers: ['It does not accelerate — the expulsion is an internal force pair, so the system’s centre of mass keeps its original motion.', 'It accelerates forward with the rocket, since the rocket is the important part.', 'It accelerates backward with the expelled gas, because gas has more speed.'], correct: 0 },
  { id: 'com-11', topic: 'com', level: 3, q: 'Why is v_COM = Σp / Σm useful during a collision?', answers: ['Momentum conservation keeps v_COM constant through the collision, so it tracks the system’s unchanging bulk motion.', 'It gives the speed of the fastest fragment after impact.', 'It always equals the final speed of both objects stuck together — even when they bounce.'], correct: 0 },
  { id: 'com-12', topic: 'com', level: 3, q: 'Two masses sit on a light rod, one heavy and one light. Discuss where the centre of mass lies.', answers: ['Closer to the heavy mass — the position average is weighted by mass.', 'Exactly halfway, because the rod balances there.', 'Closer to the light mass, since light objects are easier to move.'], correct: 0 },

  // ---------- Relative Velocity ----------
  { id: 'rel-01', topic: 'relative', level: 1, q: 'A canoeist describes a crocodile’s motion differently from an observer on the riverbank. What quantity accounts for the canoeist’s observation?', answers: ['The crocodile’s velocity measured relative to the canoeist’s frame.', 'The positive difference between their speeds, with direction discarded.', 'The riverbank velocity, which is the only physically valid motion.'], correct: 0 },
  { id: 'rel-02', topic: 'relative', level: 1, q: 'A raft A and canoe B move along the same river. Which expression gives the canoe’s velocity as measured by an observer on the raft?', answers: ['v_BA = v_B − v_A.', 'v_BA = v_A − v_B.', 'v_BA = v_A + v_B for every choice of direction.'], correct: 0 },
  { id: 'rel-03', topic: 'relative', level: 1, q: 'A scout on canoe A measures canoe B, while a scout on B measures A. How must their velocity measurements be related?', answers: ['They have equal magnitudes and opposite directions: v_BA = −v_AB.', 'They are identical vectors because both scouts observe the same two canoes.', 'Their magnitudes need not match because each scout occupies a different frame.'], correct: 0 },
  { id: 'rel-04', topic: 'relative', level: 1, q: 'Jamnani reports that a parrot is stationary while an explorer sees it moving backward. What must differ between their descriptions?', answers: ['Their frames of reference—the viewpoints relative to which position and velocity are measured.', 'The force on the parrot, because a frame of reference is a physical interaction.', 'The parrot’s true absolute velocity, which only one observer can measure.'], correct: 0 },
  { id: 'rel-05', topic: 'relative', level: 2, q: 'Two cars travel the same way at similar speeds. Explain what each driver sees.', answers: ['The other car drifts slowly, because their relative velocity is the small difference of nearly equal velocities.', 'The other car appears stationary, because matching direction cancels all motion.', 'The other car approaches rapidly, since their speeds add.'], correct: 0 },
  { id: 'rel-06', topic: 'relative', level: 2, q: 'Why does rain appear to slant toward you when you run through it?', answers: ['In your frame, your own backward velocity is added to the drops, so they meet you at an angle.', 'The raindrops speed up horizontally to match your motion.', 'Running changes the direction gravity acts on the drops.'], correct: 0 },
  { id: 'rel-07', topic: 'relative', level: 2, q: 'Two porters walk directly toward each other. Explain why their closing speed is the sum of their speeds.', answers: ['Their velocities have opposite signs, so subtracting them in v_BA leaves a large magnitude.', 'Speeds always add whenever two people are visible to each other.', 'The ground frame cancels one of the velocities, doubling the other.'], correct: 0 },
  { id: 'rel-08', topic: 'relative', level: 2, q: 'A passenger sits still on a smooth train. Discuss whether they are moving.', answers: ['They are at rest in the train’s frame but moving relative to the ground — motion depends on the frame chosen.', 'They are absolutely at rest, because they feel no motion.', 'They are absolutely moving, because the train is absolutely moving.'], correct: 0 },
  { id: 'rel-09', topic: 'relative', level: 3, q: 'A crocodile drifts at 2 m/s while a canoe paddles at 7 m/s in the same direction. Describe the crocodile’s motion as seen from the canoe.', answers: ['It moves backward at 5 m/s — the slower object falls behind in the faster object’s frame.', 'It moves ahead at 9 m/s, because the two speeds add.', 'It appears motionless, since both move the same way.'], correct: 0 },
  { id: 'rel-10', topic: 'relative', level: 3, q: 'Why does the order of subscripts matter in v_BA = v_B − v_A?', answers: ['Reversing the order reverses the subtraction, flipping the sign of the result.', 'The order is pure convention and changes nothing numerically.', 'One order gives speed, the other gives velocity.'], correct: 0 },
  { id: 'rel-11', topic: 'relative', level: 3, q: 'Explain why all motion is described as relative.', answers: ['Any measured velocity depends on the observer’s frame — there is no frame-independent rest state to compare against.', 'Because everything in the universe is moving at the same speed.', 'Because velocity cannot be measured, only estimated from distances.'], correct: 0 },
  { id: 'rel-12', topic: 'relative', level: 3, q: 'Two walkers move toward each other at different speeds. Each sees the other approaching at…', answers: ['the sum of their speeds, because their velocities point in opposite directions.', 'the difference of their speeds, since they move along one line.', 'a speed that depends only on the faster walker.'], correct: 0 },

  // ---------- Rotational Motion ----------
  { id: 'rot-01', topic: 'rotational', level: 1, q: 'Two temple gates have equal mass, but one is harder to start rotating. Which rotational quantity explains the difference?', answers: ['Moment of inertia, because it measures resistance to angular acceleration and depends on mass distribution.', 'Torque, because it is an object’s permanent resistance to turning.', 'Angular momentum, because every stationary gate already possesses it.'], correct: 0 },
  { id: 'rot-02', topic: 'rotational', level: 1, q: 'An explorer pushes a Rotorwilds gate away from its hinge and produces angular acceleration. Which quantity plays the rotational role of resultant force?', answers: ['Net torque, because τ_net = Iα.', 'Linear momentum, because p = mv determines the turning effect.', 'Power, because all rotational motion requires a continuous energy supply.'], correct: 0 },
  { id: 'rot-03', topic: 'rotational', level: 1, q: 'A guardian shifts stone counterweights farther from its axle without changing their mass. What does I = Σmr² predict?', answers: ['Its moment of inertia increases strongly because each mass contribution is weighted by r².', 'Its moment of inertia is unchanged because only total mass determines I.', 'Its moment of inertia decreases because distant masses rotate through a larger path.'], correct: 0 },
  { id: 'rot-04', topic: 'rotational', level: 1, q: 'A carved wheel completes one revolution and sweeps an arc equal to its full circumference. How is this angular displacement expressed?', answers: ['As 2π radians, since θ = s/r = 2πr/r.', 'As π radians, because a complete revolution contains two semicircles.', 'As 360 radians, because each degree is one radian.'], correct: 0 },
  { id: 'rot-05', topic: 'rotational', level: 2, q: 'Explain why moving mass outward on a wheel increases its moment of inertia.', answers: ['The radius term is squared, so distance from the axis amplifies each mass’s contribution.', 'The mass of the wheel increases as mass moves outward.', 'Outer mass experiences stronger gravity, adding to inertia.'], correct: 0 },
  { id: 'rot-06', topic: 'rotational', level: 2, q: 'Why does a force whose line of action passes through the axle produce no torque?', answers: ['Its lever arm is zero, so τ = rF sin θ vanishes — there is no turning effect.', 'The force is cancelled by the object’s weight before it can turn.', 'Forces through the axle are always internal.'], correct: 0 },
  { id: 'rot-07', topic: 'rotational', level: 2, q: 'Why do the constant angular acceleration equations mirror the linear ones?', answers: ['θ, ω and α are linked by the same rules as s, v and a, so the same algebra produces the same equations.', 'Rotational motion is too different for linear equations, so the match is a coincidence.', 'The equations only match when rotation happens at constant speed.'], correct: 0 },
  { id: 'rot-08', topic: 'rotational', level: 2, q: 'Why is ω = 2πf for steady rotation?', answers: ['Each revolution sweeps 2π radians, so radians per second equal 2π times revolutions per second.', 'The 2π converts frequency into seconds.', 'ω counts radians, and f already includes one full turn.'], correct: 0 },
  { id: 'rot-09', topic: 'rotational', level: 3, q: 'A spinning guardian pulls its arms in and spins faster. Justify this using angular momentum.', answers: ['Pulling the arms in reduces I; with no external torque L = Iω is conserved, so ω must increase.', 'Pulling the arms in creates angular momentum from the muscular effort.', 'The spin speeds up because energy is destroyed when the arms tuck in.'], correct: 0 },
  { id: 'rot-10', topic: 'rotational', level: 3, q: 'Why does angular momentum conservation require zero net external torque, not just zero net force?', answers: ['Torques change angular momentum the way forces change momentum — a force with no lever arm still causes no spin change.', 'Because any force at all will stop rotation immediately.', 'Forces and torques are the same thing, so either condition works.'], correct: 0 },
  { id: 'rot-11', topic: 'rotational', level: 3, q: 'Two wheels have equal mass; one has it all at the rim, the other at the hub. Discuss their rotational inertia.', answers: ['The rim wheel has the larger I, because its mass sits at larger radius and r is squared in Σmr².', 'Both have the same I, since the total mass is equal.', 'The hub wheel has larger I, because concentrated mass is harder to turn.'], correct: 0 },
  { id: 'rot-12', topic: 'rotational', level: 3, q: 'A wheel spins freely with no friction and no applied torque. Discuss its motion.', answers: ['Its angular velocity stays constant because its angular momentum is conserved.', 'It slows down steadily, since nothing keeps pushing it.', 'It gradually speeds up as it settles into its natural spin.'], correct: 0 },

  // ---------- Rolling Motion ----------
  { id: 'rol-01', topic: 'rolling', level: 1, q: 'A stone wheel crosses dry ground without leaving a skid mark. Which relationship must hold between its centre-of-mass speed and angular speed?', answers: ['v_COM = rω, so the contact point has zero velocity relative to the ground.', 'v_COM = 2rω, because the upper rim travels twice as fast as the centre.', 'v_COM = ω, because linear and angular speeds are interchangeable.'], correct: 0 },
  { id: 'rol-02', topic: 'rolling', level: 1, q: 'A rolling boulder descends into the Rotorwilds. Which energy model accounts for all of its macroscopic motion?', answers: ['K = ½mv_COM² + ½Iω², combining translation and rotation.', 'K = ½mv_COM² only, because rotation contributes no separate energy.', 'K = ½Iω² only, because the boulder is instantaneously rotating about its contact point.'], correct: 0 },
  { id: 'rol-03', topic: 'rolling', level: 1, q: 'The centre of a rolling seed pod advances while markings on its rim circle the centre. How should its motion be modelled?', answers: ['As translation of the centre of mass combined with rotation about the centre of mass.', 'As two translations, one parallel and one perpendicular to the ground.', 'As pure rotation about one fixed point on the ground for the entire journey.'], correct: 0 },
  { id: 'rol-04', topic: 'rolling', level: 2, q: 'Explain why the point of a rolling wheel touching the ground is instantaneously at rest.', answers: ['Its backward rotational speed rω equals the forward speed v_COM, so the two cancel at the contact point.', 'Friction freezes the contact point for an instant each turn.', 'The ground pushes the contact point backward into place.'], correct: 0 },
  { id: 'rol-05', topic: 'rolling', level: 2, q: 'Why does the top point of a rolling wheel move at 2v_COM?', answers: ['Its rotational speed rω and the translational speed v_COM point the same way, so they add.', 'The top of the wheel is lighter, so it moves faster.', 'Gravity gives the top point an extra push downward along the arc.'], correct: 0 },
  { id: 'rol-06', topic: 'rolling', level: 2, q: 'A wheel cannot maintain rolling without slipping when v ≠ rω. Explain why.', answers: ['The contact point then slides relative to the ground — the spin and the travel no longer match.', 'The wheel loses its moment of inertia when speeds mismatch.', 'Rolling requires the centre of mass to stay still.'], correct: 0 },
  { id: 'rol-07', topic: 'rolling', level: 2, q: 'A boulder rolls from rest down a slope of height h. Describe its energy budget at the bottom.', answers: ['The lost mgh has split between translational kinetic energy and rotational kinetic energy.', 'All of the mgh is translational — rotation comes free.', 'The rotation was powered by friction heating the slope.'], correct: 0 },
  { id: 'rol-08', topic: 'rolling', level: 3, q: 'A solid sphere races a hoop down the same slope, both rolling without slipping. Justify which wins.', answers: ['The sphere — its smaller moment of inertia sends less energy into rotation, leaving more for forward speed.', 'The hoop — its rim mass stores energy that releases as speed.', 'They tie, since both lose the same height and energy is conserved.'], correct: 0 },
  { id: 'rol-09', topic: 'rolling', level: 3, q: 'Why does a smaller moment of inertia give a higher speed at the bottom of a slope?', answers: ['Less of the fixed energy budget is stored as rotational kinetic energy, so more becomes translational.', 'A small-I object is effectively lighter downhill.', 'Small-I objects grip the slope better and slip less.'], correct: 0 },
  { id: 'rol-10', topic: 'rolling', level: 3, q: 'A rolling ball and a frictionless sliding block race down the same height. Discuss the result.', answers: ['The block arrives faster — none of its energy is diverted into rotation.', 'The ball arrives faster, because rolling adds extra energy.', 'They arrive together, because both conserve the same total energy.'], correct: 0 },
  { id: 'rol-11', topic: 'rolling', level: 3, q: 'Static friction acts on a wheel rolling without slipping. Explain why it does no work.', answers: ['It acts at the contact point, which is instantaneously at rest — force times zero displacement is zero work.', 'Static friction is too weak to do meaningful work.', 'Rolling motion cancels friction’s energy automatically.'], correct: 0 },
  { id: 'rol-12', topic: 'rolling', level: 3, q: 'What does ω = v/r express physically for a rolling wheel?', answers: ['The spin rate is set by how fast the wheel travels and how big it is.', 'The radius grows in proportion to the speed.', 'The angular speed is fixed once the wheel leaves the slope.'], correct: 0 },

  // ---------- Circular Motion ----------
  { id: 'cir-01', topic: 'circular', level: 1, q: 'A glowing beetle moves at constant speed around a circular temple rim. How does its velocity change during the motion?', answers: ['It remains tangent to the rim but continuously changes direction.', 'It points toward the centre and remains constant throughout the orbit.', 'It points outward, balancing the inward centripetal force.'], correct: 0 },
  { id: 'cir-02', topic: 'circular', level: 1, q: 'A vine supplies the inward force that swings a lantern in a circle. Why should “centripetal force” not be drawn as an additional force?', answers: ['It names the net inward result of real forces such as tension, gravity or friction.', 'It is an outward reaction force that cancels the vine tension.', 'It is a separate fundamental force created whenever a path curves.'], correct: 0 },
  { id: 'cir-03', topic: 'circular', level: 1, q: 'A falcon circles the temple at uniform speed. Which statement correctly distinguishes its speed, velocity and acceleration?', answers: ['Its speed is constant, while its velocity changes direction and its acceleration always points toward the centre.', 'Its velocity is constant because it returns to the same direction after every revolution.', 'Its acceleration is constant as a vector because its magnitude v²/r does not change.'], correct: 0 },
  { id: 'cir-04', topic: 'circular', level: 2, q: 'An object moves at constant speed in a circle. Explain why it is still accelerating.', answers: ['Its direction changes continuously, and a changing velocity means acceleration exists.', 'Its speed secretly rises and falls around the loop.', 'Circular paths bend space, which counts as acceleration.'], correct: 0 },
  { id: 'cir-05', topic: 'circular', level: 2, q: 'A ball whirls on a string in a horizontal circle. What provides the centripetal force?', answers: ['The tension in the string, directed along it toward the centre.', 'The ball’s weight, pulling it around the loop.', 'A centrifugal push outward from the circle’s centre.'], correct: 0 },
  { id: 'cir-06', topic: 'circular', level: 2, q: 'A car turns on a flat roundabout. What force keeps it on the circular path?', answers: ['Friction between the tyres and the road, acting inward.', 'The engine’s thrust, aimed sideways.', 'The normal force from the road surface.'], correct: 0 },
  { id: 'cir-07', topic: 'circular', level: 2, q: 'Why is “centrifugal force” a mislabel in an inertial frame?', answers: ['The outward tendency is just inertia — objects not being pushed inward would go straight, not outward.', 'Centrifugal force exists but is too small to measure.', 'It only appears when the circle is vertical.'], correct: 0 },
  { id: 'cir-08', topic: 'circular', level: 2, q: 'A conical pendulum swings in a steady circle. Describe the resultant of tension and weight.', answers: ['Horizontal, pointing to the centre — it is the centripetal force.', 'Zero, since the pendulum is not rising or falling.', 'Along the string, away from the pivot.'], correct: 0 },
  { id: 'cir-09', topic: 'circular', level: 3, q: 'In a vertical circle, explain why the string tension is largest at the bottom.', answers: ['At the bottom the string must both support the weight and provide the inward force; at the top gravity already helps pull inward.', 'The object is heaviest at the bottom of any circle.', 'The string slackens at the top, concentrating all tension at the bottom.'], correct: 0 },
  { id: 'cir-10', topic: 'circular', level: 3, q: 'Justify the minimum speed √(gr) at the top of a vertical circle.', answers: ['Gravity alone must supply the centripetal force mv²/r; any slower and the object loses contact.', 'At √(gr) the object’s weight momentarily becomes zero.', 'It is the speed where air resistance cancels gravity at the top.'], correct: 0 },
  { id: 'cir-11', topic: 'circular', level: 3, q: 'Explain the weightlessness felt at the top of a loop when travelling at exactly √(gr).', answers: ['The reaction force drops to zero — gravity alone provides all the centripetal force, so nothing pushes back on the rider.', 'Gravity switches off briefly at the top of the loop.', 'The rider is momentarily outside the circle’s force field.'], correct: 0 },
  { id: 'cir-12', topic: 'circular', level: 3, q: 'A banked curve needs no friction at its ideal speed. Justify this.', answers: ['The normal force resolves so its vertical part balances weight and its inward part supplies the centripetal force.', 'Banking removes gravity from the turn entirely.', 'The banking makes friction act vertically, where it cannot slow the car.'], correct: 0 },

  // ---------- Orbital Motion ----------
  { id: 'orb-01', topic: 'orbital', level: 1, q: 'A temple beacon circles Jamnanji without continuous thrust. Which interaction supplies the required centripetal force?', answers: ['Gravitational attraction toward Jamnanji’s centre.', 'Small tangential thrusters that continually push it forward.', 'Atmospheric pressure acting inward at orbital altitude.'], correct: 0 },
  { id: 'orb-02', topic: 'orbital', level: 1, q: 'Why does orbital speed not depend on the satellite’s mass?', answers: ['The satellite’s mass cancels when gravitational force is set equal to mv²/r.', 'Small satellites are too light to affect their own motion.', 'Mass is folded into the constant G.'], correct: 0 },
  { id: 'orb-03', topic: 'orbital', level: 2, q: 'Explain why astronauts feel weightless while orbiting.', answers: ['The station and the astronaut fall toward Earth together — in free fall, nothing pushes back on them.', 'They are beyond Earth’s gravity, which stops at orbital height.', 'The station spins to cancel their weight.'], correct: 0 },
  { id: 'orb-04', topic: 'orbital', level: 2, q: 'Why doesn’t a satellite crash into Earth despite gravity acting on it?', answers: ['Gravity curves its path into a circle — it is continuously falling while also moving sideways fast enough to keep missing the planet.', 'Its engines fire backward to hold it up.', 'At orbital height gravity has weakened to almost nothing.'], correct: 0 },
  { id: 'orb-05', topic: 'orbital', level: 2, q: 'A satellite moves to a higher circular orbit. Explain what happens to its speed.', answers: ['It decreases — orbital speed falls as the square root of radius grows.', 'It increases, since higher orbits have more energy.', 'It stays constant, because the orbit is still circular.'], correct: 0 },
  { id: 'orb-06', topic: 'orbital', level: 2, q: 'Why are the units of g both N kg⁻¹ and m s⁻²?', answers: ['Force per unit mass is an acceleration — the two units describe the same quantity.', 'They are two different quantities that happen to share a symbol.', 'N kg⁻¹ applies on Earth, m s⁻² only in orbit.'], correct: 0 },
  { id: 'orb-07', topic: 'orbital', level: 3, q: 'Use T = 2π√(r³/GM) to justify why higher orbits have longer periods.', answers: ['The period grows with r raised to the power 3/2, so a larger radius always means a longer period.', 'Higher satellites move at the same speed but trace a bigger loop only.', 'Gravity strengthens with r, slowing the satellite to a crawl.'], correct: 0 },
  { id: 'orb-08', topic: 'orbital', level: 3, q: 'Explain why gravitational field strength falls off as 1/r².', answers: ['The same field influence spreads over the surface of an ever-larger sphere as r grows.', 'The Earth’s mass decreases with distance from it.', 'The atmosphere absorbs field strength closer to the ground.'], correct: 0 },
  { id: 'orb-09', topic: 'orbital', level: 3, q: 'Two satellites share an orbit but have very different masses. Compare their speeds.', answers: ['Their speeds are equal — mass cancels from the orbital speed equation.', 'The heavier satellite moves faster to stay up.', 'The lighter satellite moves faster, being easier to accelerate.'], correct: 0 },
  { id: 'orb-10', topic: 'orbital', level: 3, q: 'A navigation beacon occupies a medium circular orbit while a broadcast beacon is geostationary at a larger radius. Compare their speeds and periods.', answers: ['The navigation beacon moves faster and completes each orbit sooner, since orbital speed decreases while period increases with radius.', 'The navigation beacon moves slower because the stronger gravitational field opposes its motion.', 'Both have the same period because all circular satellites complete one orbit per planetary day.'], correct: 0 },
  { id: 'orb-11', topic: 'orbital', level: 3, q: 'Why does v = 2πr/T hold for circular orbits?', answers: ['Each orbit covers one circumference 2πr in one period T — distance over time.', 'The radius is swept once per period in a straight line.', '2π converts the orbital period into radians.'], correct: 0 },
  { id: 'orb-12', topic: 'orbital', level: 3, q: 'A probe doubles its orbital radius. Discuss the change in gravitational field strength it experiences.', answers: ['The field strength quarters, because g scales as 1/r².', 'The field strength halves, following the radius directly.', 'The field strength doubles — nearer the planet it was weaker.'], correct: 0 },

  // ---------- Simple Harmonic Motion ----------
  { id: 'shm-01', topic: 'shm', level: 1, q: 'A crystal displaced from the centre of a temple trap experiences F = −kx. Why does this condition produce simple harmonic motion?', answers: ['The restoring force is proportional to displacement and always directed toward equilibrium.', 'Any force that repeats in time automatically produces simple harmonic motion.', 'A constant one-direction force returns the crystal at equal time intervals.'], correct: 0 },
  { id: 'shm-02', topic: 'shm', level: 1, q: 'A resonant seed pod obeys a = −ω²x. At which positions is the magnitude of its acceleration greatest, and why?', answers: ['At the extreme displacements, because |a| is proportional to |x|.', 'At equilibrium, because this is where its speed is greatest.', 'Halfway to each extreme, because acceleration and velocity peak together.'], correct: 0 },
  { id: 'shm-03', topic: 'shm', level: 1, q: 'A hanging temple lantern oscillates about a stable central position. What additional condition would make the motion simple harmonic?', answers: ['Its acceleration must be proportional to displacement and directed toward equilibrium.', 'Its path must be the projection of a real object moving in a circle.', 'Its motion must eventually stop because of resistive forces.'], correct: 0 },
  { id: 'shm-04', topic: 'shm', level: 2, q: 'Explain why speed is maximum at the equilibrium position.', answers: ['All the oscillator’s energy is kinetic there — the potential energy is zero and the total is constant.', 'The restoring force is strongest at equilibrium, flinging the mass through.', 'Equilibrium is where acceleration and velocity both peak together.'], correct: 0 },
  { id: 'shm-05', topic: 'shm', level: 2, q: 'At the extremes of an oscillation, the energy of an ideal oscillator is…', answers: ['entirely potential — the mass is momentarily still.', 'entirely kinetic — the turning points move fastest.', 'half kinetic and half potential, on average.'], correct: 0 },
  { id: 'shm-06', topic: 'shm', level: 2, q: 'Why is there a minus sign in a = −ω²x?', answers: ['The acceleration always opposes the displacement, pointing back toward equilibrium.', 'The energy of an oscillator counts as negative.', 'It shows the velocity decreasing each cycle.'], correct: 0 },
  { id: 'shm-07', topic: 'shm', level: 2, q: 'A heavier mass is hung on the same spring. Discuss the effect on the period.', answers: ['The period lengthens, since T = 2π√(m/k) grows with mass.', 'The period shortens — heavier means faster.', 'The period is unchanged — the spring does not know the mass.'], correct: 0 },
  { id: 'shm-08', topic: 'shm', level: 2, q: 'When does resonance occur?', answers: ['When the driving frequency matches the system’s natural frequency, producing maximum amplitude.', 'When the driving force is as large as possible.', 'When all damping is removed from the system.'], correct: 0 },
  { id: 'shm-09', topic: 'shm', level: 2, q: 'What does damping do to an oscillation?', answers: ['Resistive forces drain mechanical energy, so the amplitude decays over time.', 'Damping increases the frequency while shrinking the amplitude.', 'Damping stores energy for the next swing.'], correct: 0 },
  { id: 'shm-10', topic: 'shm', level: 3, q: 'Discuss the energy changes over one full oscillation of an ideal mass–spring system.', answers: ['Energy swaps between potential and kinetic twice per cycle, while the total stays constant.', 'Energy is lost each swing and replaced at the extremes.', 'Kinetic energy stays constant while potential ripples.'], correct: 0 },
  { id: 'shm-11', topic: 'shm', level: 3, q: 'A pendulum’s bob is replaced with a heavier one. Justify the effect on the period.', answers: ['None — the mass cancels out, leaving T = 2π√(l/g) dependent only on length and g.', 'The period grows with the extra mass.', 'The period shrinks — heavier bobs swing tighter.'], correct: 0 },
  { id: 'shm-12', topic: 'shm', level: 3, q: 'A system is driven at a frequency below its natural frequency. Describe its response.', answers: ['It oscillates at the driving frequency with a smaller-than-maximum amplitude.', 'It refuses to move until the frequencies match.', 'It ignores the driver and oscillates at its natural frequency regardless.'], correct: 0 },

  // ---------- Momentum and Impulse (extended) ----------
  { id: 'mom-13', topic: 'momentum', level: 2, q: 'A crash into a softer barrier changes the force–time graph. Discuss the area and the peak.', answers: ['The area stays the same — same momentum change — but the force peak is lower and spread over a longer time.', 'The area grows because the softer barrier adds extra impulse.', 'The peak force stays the same; only the graph stretches sideways.'], correct: 0 },
  { id: 'mom-14', topic: 'momentum', level: 2, q: 'Two mud-covered boulders collide and stick. For their fixed initial momenta, why does this outcome represent the greatest possible kinetic-energy loss?', answers: ['Momentum still fixes their shared final velocity, while sticking removes all relative motion between them and transfers the maximum permitted kinetic energy to other forms.', 'Momentum conservation requires their final kinetic energy to be zero, regardless of their initial total momentum.', 'Sticking preserves more kinetic energy than rebounding because the boulders no longer move relative to each other.'], correct: 0 },
  { id: 'mom-15', topic: 'momentum', level: 2, q: 'A seed pod strikes a temple wall and rebounds. Which vector method correctly determines its change in momentum?', answers: ['Use Δp = p_f − p_i, equivalently adding the reversed initial momentum vector to the final vector.', 'Add the two momentum magnitudes in every collision, regardless of their directions.', 'Subtract the smaller momentum magnitude from the larger and assign the final direction.'], correct: 0 },

  // ---------- Energy and Work (extended) ----------
  { id: 'ene-13', topic: 'energy', level: 1, q: 'A vine does positive work while accelerating a supply sled. Which energy statement is equivalent to this description?', answers: ['The net work equals the sled’s change in energy: W = ΔE.', 'Work is the rate at which the sled’s energy changes, so W = ΔE/Δt.', 'Work is the impulse delivered to the sled, so W = FΔt.'], correct: 0 },
  { id: 'ene-14', topic: 'energy', level: 3, q: 'A vine cart enters the bottom of a vertical loop and reaches the top without resistive losses. Justify using energy rather than a constant-acceleration model to relate its two speeds.', answers: ['Its height and resultant force change around the loop, while conservation of mechanical energy links the endpoint speeds directly through the 2r height gain.', 'Circular motion automatically keeps its speed constant, so no force analysis is required.', 'The resultant force is constant around the loop, making the constant-acceleration equations equivalent to energy conservation.'], correct: 0 },
  { id: 'ene-15', topic: 'energy', level: 2, q: 'Two springs are stretched by the same amount. Discuss which stores more elastic energy.', answers: ['The stiffer one — a larger spring constant k gives more energy at the same extension.', 'The softer one, because it stretches more willingly.', 'Both store the same, since the extensions match.'], correct: 0 },

  // ---------- Centre of Mass (extended) ----------
  { id: 'com-13', topic: 'com', level: 2, q: 'In a_COM = Σmᵢaᵢ/Σmᵢ, what does the averaging mean physically?', answers: ['Heavier parts’ accelerations count more in the centre-of-mass average.', 'Every part’s acceleration counts equally regardless of mass.', 'Only the external parts’ accelerations appear in the sum.'], correct: 0 },
  { id: 'com-14', topic: 'com', level: 1, q: 'A tumbling relic follows a projectile path while rotating rapidly. Why does a centre-of-mass model simplify the analysis?', answers: ['It allows translation of the centre of mass and rotation about it to be treated separately.', 'It removes the need to consider external forces such as gravity.', 'It transforms to a frame in which the system’s total momentum is always zero.'], correct: 0 },

  // ---------- Rotational Motion (extended) ----------
  { id: 'rot-13', topic: 'rotational', level: 1, q: 'A freely spinning jungle mechanism preserves a quantity when no external torque acts. Which quantity is conserved, and how is it expressed for a rigid body?', answers: ['Angular momentum, L = Iω.', 'Torque, τ = Fr, because the turning effect remains stored.', 'Moment of inertia, I = mr², because it measures the mechanism’s motion.'], correct: 0 },
  { id: 'rot-14', topic: 'rotational', level: 2, q: 'Tangential acceleration a_t = rα tells you that…', answers: ['points farther from the axis accelerate more for the same angular acceleration.', 'every point on the wheel shares one acceleration value.', 'angular acceleration grows with distance from the axis.'], correct: 0 },
  { id: 'rot-15', topic: 'rotational', level: 3, q: 'Justify why L = mvr for a point mass moving in a circle.', answers: ['I = mr² and ω = v/r, so L = Iω = mr² × v/r = mvr.', 'Momentum multiplied by time naturally gives angular momentum.', 'v and r are independent quantities that both store spin.'], correct: 0 },
  { id: 'rot-16', topic: 'rotational', level: 2, q: 'Why is τ_net = Iα called Newton’s second law for rotation?', answers: ['Net torque changes rotational motion while I resists that change — the exact role F and m play linearly.', 'It converts force into angle using the radius as a pivot.', 'It only holds while the object spins at constant speed.'], correct: 0 },

  // ---------- Circular Motion (extended) ----------
  { id: 'cir-13', topic: 'circular', level: 1, q: 'Two parrots follow circular paths; one maintains constant speed while the other speeds up. What additional acceleration does the second parrot require?', answers: ['A tangential component that changes its speed, as well as the radial component that changes direction.', 'No acceleration, because both paths remain circular.', 'An outward component that turns sections of its path into straight lines.'], correct: 0 },
  { id: 'cir-14', topic: 'circular', level: 3, q: 'Use energy conservation to link the top and bottom of a vertical circle (no losses).', answers: ['½mv²_top + mg(2r) = ½mv²_bottom — the height difference 2r accounts for the speed change.', 'The top speed always equals √(5gr) whatever the bottom speed.', 'The bottom energy exceeds the top by mg r, one radius of height.'], correct: 0 },
  { id: 'cir-15', topic: 'circular', level: 3, q: 'A car takes a banked curve below the ideal speed. Discuss what happens.', answers: ['It tends to slide down the slope, so friction acts up the slope to help hold the line.', 'It tends to slide up the slope, with friction acting down.', 'It leaves the surface because banking requires minimum speed.'], correct: 0 },

  // ---------- Orbital Motion (extended) ----------
  { id: 'orb-13', topic: 'orbital', level: 2, q: 'The same satellite orbits a heavier planet at the same radius. Discuss its new orbital speed.', answers: ['Greater — v = √(GM/r) grows with the central mass M.', 'Smaller — the stronger gravity drags it to a crawl.', 'Unchanged — the mass cancels out of the orbit equation.'], correct: 0 },
  { id: 'orb-14', topic: 'orbital', level: 3, q: 'Why do we set F_g = F_c to derive the orbital speed?', answers: ['Gravity is the force doing the centripetal job, so both expressions describe one and the same force.', 'To average the gravitational and centripetal forces into a net value.', 'Because a satellite needs two forces acting on it to stay in orbit.'], correct: 0 },
  { id: 'orb-15', topic: 'orbital', level: 2, q: 'From T = 2π√(r³/GM), what relationship between period and radius follows?', answers: ['T² is proportional to r³ — squaring removes the square root.', 'T is proportional to r³ directly.', 'T² is proportional to r, one power of the radius.'], correct: 0 },

  // ---------- Simple Harmonic Motion (extended) ----------
  { id: 'shm-13', topic: 'shm', level: 1, q: 'A Resonant Heart moves between x = −0.30 m and x = +0.30 m about equilibrium. What is its amplitude, and why?', answers: ['0.30 m, because amplitude is the maximum displacement from equilibrium.', '0.60 m, because amplitude is the full distance between turning points.', '1.20 m, because amplitude is the distance travelled in a complete cycle.'], correct: 0 },
  { id: 'shm-14', topic: 'shm', level: 2, q: 'A pendulum is made longer. Discuss the effect on its period.', answers: ['The period increases, since T = 2π√(l/g) grows with length.', 'The period decreases — longer pendulums snap back faster.', 'No change — only mass affects a pendulum’s period.'], correct: 0 },
  { id: 'shm-15', topic: 'shm', level: 1, q: 'Temple drums apply repeated pushes to a hanging bridge. What distinguishes the resulting forced oscillation from a free oscillation?', answers: ['An external periodic force drives the bridge and sets the steady-state oscillation frequency.', 'Friction alone supplies the restoring force and fixes the bridge’s frequency.', 'The bridge oscillates only through its own restoring force, with no external energy input.'], correct: 0 },
  { id: 'shm-16', topic: 'shm', level: 2, q: 'Tides, a vine-mounted relic and a temple tower during an earthquake all move repeatedly about characteristic positions. What common feature justifies describing them as oscillatory?', answers: ['Each exhibits repeated variation about an equilibrium or mean state, even though the restoring mechanisms and regularity differ.', 'Only the vine-mounted relic qualifies, because oscillations must be perfectly periodic.', 'Only pendulum-like systems qualify, because every oscillator must move along a circular arc.'], correct: 0 },

  // ---------- Momentum and Impulse (expedition set) ----------
  { id: 'mom-16', topic: 'momentum', level: 2, q: 'A light canoe and a heavily loaded raft receive equal impulses from stretched vines. Compare their resulting momentum changes and velocity changes.', answers: ['Their momentum changes are equal, but the lighter canoe has the larger velocity change because Δv = Δp/m.', 'The loaded raft gains more momentum because its mass is larger, while both have the same velocity change.', 'The canoe gains more momentum and more velocity because impulse is inversely proportional to mass.'], correct: 0 },
  { id: 'mom-17', topic: 'momentum', level: 3, q: 'An explorer jumps forward from a stationary raft. Discuss the motion of the explorer–raft system while horizontal external forces are negligible.', answers: ['They gain equal and opposite momenta, so the raft recoils more slowly if it is more massive and the system’s centre-of-mass velocity remains zero.', 'They gain equal and opposite velocities, so their different masses do not affect the recoil.', 'The explorer’s jump creates net forward momentum because muscular energy is added to the system.'], correct: 0 },
  { id: 'mom-18', topic: 'momentum', level: 3, q: 'A clay idol moving east strikes a lighter stationary idol and they stick. Without calculating, justify why their shared speed is eastward but lower than the first idol’s initial speed.', answers: ['Eastward momentum is conserved but is shared by a greater combined mass, so the common velocity must be smaller.', 'Kinetic energy is conserved, so the original speed is divided equally between the idols.', 'The stationary idol contributes westward momentum, reducing both the direction and magnitude of the total.'], correct: 0 },
  { id: 'mom-19', topic: 'momentum', level: 2, q: 'A force–time graph for a rhino striking a gate has a sharp peak. A padded gate produces the same graph area with a lower peak. What can be concluded?', answers: ['Both gates give the rhino the same impulse, but the padded gate spreads that momentum change over more time and lowers the maximum force.', 'The padded gate gives less impulse because its peak force is lower, even though the areas match.', 'Both gates exert the same force at every instant because their total impulses are equal.'], correct: 0 },
  { id: 'mom-20', topic: 'momentum', level: 3, q: 'Two vine carts collide on a track while a small friction force acts. When is treating momentum as conserved still a defensible approximation?', answers: ['When the collision time is so short that the external friction impulse is negligible compared with the carts’ exchanged impulses.', 'Whenever the friction force is constant, because constant external forces cannot change total momentum.', 'Only when the collision is elastic, because kinetic-energy conservation guarantees momentum conservation.'], correct: 0 },

  // ---------- Energy and Work (expedition set) ----------
  { id: 'ene-16', topic: 'energy', level: 2, q: 'Two routes climb to the same canopy platform: one is steep and short, the other gentle and long. Ignoring friction, compare the work done against gravity.', answers: ['The work is the same on both routes because it depends on the vertical height gain mgΔh, not the path.', 'The steep route requires more work because its force component along the path is larger.', 'The long route requires more work because work always increases with total distance travelled.'], correct: 0 },
  { id: 'ene-17', topic: 'energy', level: 3, q: 'A vine catapult launches two equal stones with the same speed, one vertically and one at an angle. Ignoring drag, compare their maximum increases in gravitational potential energy.', answers: ['The vertical launch gains more because all its initial kinetic energy can become gravitational potential energy, while the angled stone retains horizontal kinetic energy.', 'They gain the same because their initial kinetic energies are equal and all kinetic energy vanishes at maximum height.', 'The angled launch gains more because its longer curved path lets gravity perform more negative work.'], correct: 0 },
  { id: 'ene-18', topic: 'energy', level: 3, q: 'A supply sled descends a rough jungle slope at constant speed. Discuss the energy transfers during the descent.', answers: ['Its kinetic energy is unchanged; the lost gravitational potential energy is transferred mainly to thermal energy by friction.', 'Its gravitational potential energy becomes kinetic energy, but friction removes the extra speed afterward.', 'No energy transfer occurs because constant speed means the resultant force and all work are zero.'], correct: 0 },
  { id: 'ene-19', topic: 'energy', level: 2, q: 'A temple winch lifts the same relic through the same height, first slowly and then quickly. Compare the work and average power, ignoring losses.', answers: ['The work is the same, but the quicker lift has greater average power because the same energy transfer occurs in less time.', 'The quicker lift requires more work because greater power always means more energy is transferred.', 'Both work and power are the same because the relic’s mass and height are unchanged.'], correct: 0 },
  { id: 'ene-20', topic: 'energy', level: 3, q: 'A compressed spring launches a cart up a rough track, where it stops below the height predicted for a frictionless track. Account for the full energy change.', answers: ['Initial elastic energy becomes gravitational potential energy plus thermal energy, with zero kinetic energy at the turning point.', 'The missing height shows that some energy was destroyed by friction before the cart stopped.', 'All elastic energy becomes gravitational potential energy; friction changes only the time taken to climb.'], correct: 0 },

  // ---------- Centre of Mass (expedition set) ----------
  { id: 'com-15', topic: 'com', level: 2, q: 'An explorer walks from one end of a freely floating raft to the other. Explain why the raft moves backward.', answers: ['With negligible horizontal external force, the system’s centre of mass must remain fixed, so the raft shifts opposite the explorer.', 'The raft moves because the explorer’s weight becomes an unbalanced horizontal force.', 'The raft must gain the same backward velocity as the explorer’s forward velocity.'], correct: 0 },
  { id: 'com-16', topic: 'com', level: 3, q: 'A vine bridge holds two supply crates at different positions. One crate is twice as massive as the other. Justify where the pair’s centre of mass lies.', answers: ['It lies between them but closer to the heavier crate, with distances from the centre of mass inversely proportional to their masses.', 'It lies at the midpoint because both crates contribute one position to the average.', 'It lies inside the heavier crate regardless of the separation between them.'], correct: 0 },
  { id: 'com-17', topic: 'com', level: 3, q: 'A mid-air seed pod splits into two fragments under an internal spring force. Compare the fragments’ paths with the path of their combined centre of mass.', answers: ['The fragments follow separate paths, but their mass-weighted centre continues the projectile trajectory set by gravity.', 'The centre of mass follows the heavier fragment because that fragment contains most of the system’s momentum.', 'The spring force gives the centre of mass an additional acceleration in the direction of the faster fragment.'], correct: 0 },
  { id: 'com-18', topic: 'com', level: 2, q: 'An uneven idol stands on a narrow pedestal. Which condition determines whether it topples after being nudged?', answers: ['It topples when the vertical line through its centre of mass falls outside its base of support, producing an unbalanced torque.', 'It topples whenever its geometric centre moves, even if its weight still acts within the base.', 'It remains stable as long as any part of the idol touches the pedestal.'], correct: 0 },
  { id: 'com-19', topic: 'com', level: 3, q: 'A canoe takes on rainwater at its bow. Discuss how this redistribution affects its centre of mass and rotational stability.', answers: ['The centre of mass shifts toward the bow; its changed position alters gravitational torques and can make tipping or pitching easier.', 'The centre of mass remains fixed because adding water changes total mass but not mass distribution.', 'The centre of mass shifts away from the bow because heavier regions push the average toward the lighter end.'], correct: 0 },

  // ---------- Relative Velocity (expedition set) ----------
  { id: 'rel-13', topic: 'relative', level: 2, q: 'A canoe points directly across a river but the current carries it downstream. Explain the canoe’s ground velocity.', answers: ['It is the vector sum of the canoe’s velocity relative to the water and the water’s velocity relative to the bank.', 'It equals the canoe’s across-river speed because perpendicular current cannot affect its path.', 'It is the difference of the two speed magnitudes, directed toward the faster motion.'], correct: 0 },
  { id: 'rel-14', topic: 'relative', level: 3, q: 'An explorer wants to land directly opposite on a flowing river. Justify why the canoe must point upstream rather than straight across.', answers: ['Its upstream velocity component relative to the water must cancel the downstream current, leaving a resultant velocity directly across.', 'Pointing upstream increases the river current until the two speeds become equal.', 'The canoe must aim upstream because relative velocities are always opposite to ground velocities.'], correct: 0 },
  { id: 'rel-15', topic: 'relative', level: 2, q: 'Two parrots fly east at 12 m/s and 8 m/s relative to the ground. Describe the slower parrot’s velocity in the faster parrot’s frame.', answers: ['It is 4 m/s west because v_slow,fast = 8 − 12 = −4 m/s.', 'It is 20 m/s east because velocities in the same direction must be added.', 'It is stationary because both velocities point east.'], correct: 0 },
  { id: 'rel-16', topic: 'relative', level: 3, q: 'Rain falls vertically in the ground frame but strikes the front of a moving jungle rover. Use relative velocity to explain the observation.', answers: ['Subtracting the rover’s forward velocity gives the rain a backward horizontal component in the rover frame, so its relative velocity is slanted.', 'The rover’s motion exerts a horizontal force that bends each raindrop before impact.', 'The rain remains vertical in every inertial frame because gravity fixes an absolute direction of motion.'], correct: 0 },
  { id: 'rel-17', topic: 'relative', level: 3, q: 'A raft drifts downstream while an explorer walks upstream across its deck. Under what condition is the explorer stationary relative to the bank?', answers: ['When the explorer’s upstream velocity relative to the raft equals the raft’s downstream velocity relative to the bank.', 'When the explorer and raft have equal speeds in the same downstream direction.', 'Only when both the explorer and raft are stationary relative to the water.'], correct: 0 },

  // ---------- Rotational Motion (expedition set) ----------
  { id: 'rot-17', topic: 'rotational', level: 2, q: 'Two explorers push with equal force on a temple door, one near the hinge and one at the outer edge. Compare their torques.', answers: ['The outer push produces more torque because the perpendicular lever arm is larger.', 'Their torques are equal because torque depends only on force magnitude.', 'The near-hinge push produces more torque because the door resists motion most strongly there.'], correct: 0 },
  { id: 'rot-18', topic: 'rotational', level: 3, q: 'A rotating platform contracts inward while no external torque acts. Discuss both angular momentum and rotational kinetic energy.', answers: ['Angular momentum remains constant, angular speed increases as I decreases, and kinetic energy can increase through work done during contraction.', 'Both angular momentum and kinetic energy remain constant, so angular speed cannot change.', 'Angular momentum increases because pulling inward creates additional rotational motion.'], correct: 0 },
  { id: 'rot-19', topic: 'rotational', level: 2, q: 'A light vine is wound around two axles of different radii. The same tangential force is applied to each. Which axle has the greater angular acceleration if their moments of inertia are equal?', answers: ['The larger-radius axle, because τ = rF is greater and α = τ/I.', 'The smaller-radius axle, because a shorter lever arm concentrates the force.', 'They have equal angular acceleration because the tangential forces match.'], correct: 0 },
  { id: 'rot-20', topic: 'rotational', level: 3, q: 'A flywheel and a solid disk have equal mass and radius. The flywheel has more mass near its rim. Compare their response to the same net torque.', answers: ['The flywheel has greater moment of inertia and therefore smaller angular acceleration from α = τ/I.', 'The flywheel accelerates faster because rim mass experiences a larger tangential speed.', 'They accelerate equally because torque determines angular acceleration independently of mass distribution.'], correct: 0 },
  { id: 'rot-21', topic: 'rotational', level: 3, q: 'A freely spinning guardian throws a stone tangentially from its rim. Explain the guardian’s rotational response.', answers: ['The stone carries angular momentum away, so the guardian gains angular momentum in the opposite direction to conserve the system total.', 'The guardian keeps the same angular velocity because throwing is an internal action.', 'The guardian stops because the stone removes all angular momentum regardless of its mass and speed.'], correct: 0 },

  // ---------- Rolling Motion (expedition set) ----------
  { id: 'rol-13', topic: 'rolling', level: 2, q: 'A rolling wheel suddenly reaches slick mud and begins to slide while keeping the same angular speed. What relationship has failed?', answers: ['v_COM = rω no longer holds, so the contact point moves relative to the ground.', 'v_COM = 2rω no longer holds, so the top of the wheel becomes stationary.', 'The wheel has lost all rotational kinetic energy because friction is absent.'], correct: 0 },
  { id: 'rol-14', topic: 'rolling', level: 3, q: 'A hoop and a solid cylinder roll from rest down the same slope without slipping. Use their mass distributions to compare their accelerations.', answers: ['The solid cylinder accelerates faster because its smaller I/(mr²) leaves a larger fraction of mgh for translational motion.', 'The hoop accelerates faster because its larger moment of inertia stores more energy and pulls it downhill.', 'They accelerate equally because mass, radius and vertical energy loss are identical.'], correct: 0 },
  { id: 'rol-15', topic: 'rolling', level: 3, q: 'A driven cart wheel rolls without slipping while speeding up on level ground. Explain the role of static friction.', answers: ['Static friction supplies the horizontal interaction needed to coordinate translation and rotation, while the contact point remains instantaneously at rest.', 'Static friction must do negative work and reduce the cart’s mechanical energy whenever the wheel speeds up.', 'No friction acts during rolling without slipping because the contact point has zero velocity.'], correct: 0 },
  { id: 'rol-16', topic: 'rolling', level: 2, q: 'A boulder rolls onto level ground with v_COM = rω. What is the speed of its highest point relative to the ground?', answers: ['2v_COM, because translational and rotational velocities add at the top.', 'v_COM, because every point on a rigid body shares the centre-of-mass speed.', 'Zero, because pure rolling makes every rim point instantaneously stationary.'], correct: 0 },
  { id: 'rol-17', topic: 'rolling', level: 3, q: 'A rolling object and a sliding object start with equal total kinetic energy and climb lossless tracks; the rolling track supplies enough static friction to prevent slipping. Compare their maximum heights.', answers: ['They reach the same height because each converts the same total kinetic energy into gravitational potential energy, while static friction coordinates the rolling motion without dissipating energy.', 'The rolling object reaches lower because rotational kinetic energy cannot be converted into gravitational potential energy.', 'The sliding object reaches lower because it lacks rotational energy in addition to translational energy.'], correct: 0 },

  // ---------- Circular Motion (expedition set) ----------
  { id: 'cir-16', topic: 'circular', level: 2, q: 'A vine lantern moves twice as fast in the same circular path. How must the required centripetal force change?', answers: ['It quadruples because F_c = mv²/r and the speed is squared.', 'It doubles because force is directly proportional to speed.', 'It remains unchanged because the radius and mass are unchanged.'], correct: 0 },
  { id: 'cir-17', topic: 'circular', level: 3, q: 'A cart crests a circular jungle hill. Explain why passengers feel lighter as the cart’s speed increases.', answers: ['A larger downward centripetal acceleration is required, so gravity must exceed the upward normal force by a greater amount and the normal force decreases.', 'The passengers’ gravitational force decreases with speed, reducing both weight and centripetal force.', 'The normal force increases to push the passengers more strongly toward the centre below the hill.'], correct: 0 },
  { id: 'cir-18', topic: 'circular', level: 3, q: 'A conical pendulum is made to rotate faster while its length stays fixed. Discuss the change in its angle from vertical.', answers: ['The angle increases because a larger horizontal component of tension is needed for centripetal acceleration relative to the vertical component balancing weight.', 'The angle decreases because faster motion pulls the bob closer to the rotation axis.', 'The angle remains fixed because only pendulum length determines the circular geometry.'], correct: 0 },
  { id: 'cir-19', topic: 'circular', level: 2, q: 'Mud reduces the available friction on a flat circular track. What happens to the maximum safe speed at the same radius?', answers: ['It decreases because friction supplies the centripetal force and v_max = √(μgr).', 'It increases because lower friction allows the cart to turn with less resistance.', 'It is unchanged because centripetal force depends only on mass and radius.'], correct: 0 },
  { id: 'cir-20', topic: 'circular', level: 3, q: 'A stone is released when the vine holding it in horizontal circular motion snaps. Describe and justify its immediate path in the ground frame.', answers: ['It moves along the tangent with its instantaneous velocity, then curves downward under gravity because the inward tension has vanished.', 'It flies radially outward because centrifugal force remains after the vine snaps.', 'It continues around the same circle briefly because it retains centripetal acceleration.'], correct: 0 },

  // ---------- Orbital Motion (expedition set) ----------
  { id: 'orb-16', topic: 'orbital', level: 2, q: 'A beacon in circular orbit fires a brief forward thrust and enters a higher orbit. Why can the transfer not be described as simply moving outward at constant speed?', answers: ['The thrust changes its orbital energy and produces an elliptical transfer path in which both speed and gravitational potential energy change.', 'Forward thrust immediately creates a larger circular orbit with the same speed.', 'The beacon moves radially outward because tangential velocity has no effect on orbital shape.'], correct: 0 },
  { id: 'orb-17', topic: 'orbital', level: 3, q: 'Two beacons orbit at radii r and 4r around the same jungle world. Compare their orbital speeds and periods.', answers: ['The outer beacon has half the speed and eight times the period because v ∝ r⁻¹ᐟ² and T ∝ r³ᐟ².', 'The outer beacon has four times the speed and four times the period because its path is four times larger.', 'The outer beacon has one-quarter the speed and sixteen times the period because both quantities follow r².'], correct: 0 },
  { id: 'orb-18', topic: 'orbital', level: 3, q: 'An orbiting explorer feels weightless even though gravity is strong. Distinguish weightlessness from the absence of gravity.', answers: ['Gravity accelerates both explorer and craft together, so no supporting normal force acts and apparent weight is zero.', 'Gravity is cancelled by an equal outward centrifugal force, making the net gravitational field zero.', 'The explorer’s mass becomes zero in orbit, so gravity can exert no force.'], correct: 0 },
  { id: 'orb-19', topic: 'orbital', level: 2, q: 'A planet has twice the mass of Jamnanji but the same radius. Compare the gravitational field strengths at their surfaces.', answers: ['The heavier planet’s field is twice as strong because g = GM/r².', 'The fields are equal because surface radius alone determines gravitational strength.', 'The heavier planet’s field is four times as strong because mass is squared in the field equation.'], correct: 0 },
  { id: 'orb-20', topic: 'orbital', level: 3, q: 'A circular-orbit beacon suddenly loses speed without changing position. Predict the resulting orbit.', answers: ['It enters an elliptical orbit with that point as the high point, falling inward as gravity curves its slower tangential motion.', 'It moves into a larger circular orbit because slower satellites always orbit farther away.', 'It falls radially straight down because any speed below circular speed removes all sideways motion.'], correct: 0 },

  // ---------- Simple Harmonic Motion (expedition set) ----------
  { id: 'shm-17', topic: 'shm', level: 2, q: 'A spring-mounted idol is released from twice its previous amplitude. For ideal SHM, compare its period and total energy.', answers: ['Its period is unchanged, while its total energy quadruples because E = ½kA².', 'Its period doubles and its energy doubles because both are proportional to amplitude.', 'Its period halves while its energy remains constant because it travels farther each cycle.'], correct: 0 },
  { id: 'shm-18', topic: 'shm', level: 3, q: 'A resonant bridge is driven close to its natural frequency. Explain why damping limits the amplitude.', answers: ['Resistive forces dissipate energy each cycle, so the steady amplitude occurs when energy supplied by the driver balances energy lost.', 'Damping shifts all the bridge’s energy into potential form at resonance.', 'Damping removes the restoring force, preventing the bridge from reaching equilibrium.'], correct: 0 },
  { id: 'shm-19', topic: 'shm', level: 2, q: 'At what positions does an ideal oscillator have equal kinetic and potential energies?', answers: ['At |x| = A/√2, because ½kx² equals half the total energy ½kA².', 'At x = 0, because both energies are zero at equilibrium.', 'At |x| = A/2, because half the amplitude must mean half of each energy.'], correct: 0 },
  { id: 'shm-20', topic: 'shm', level: 3, q: 'A mass–spring trap is taken to a jungle world with weaker gravity but remains horizontal. Discuss its period and equilibrium position.', answers: ['Neither changes due to gravity in the ideal horizontal model; T = 2π√(m/k) and horizontal equilibrium is set by the spring.', 'The period increases because weaker gravity provides a weaker restoring force.', 'The equilibrium shifts and the period decreases because the mass effectively becomes lighter.'], correct: 0 },
  { id: 'shm-21', topic: 'shm', level: 3, q: 'A pendulum clock is moved to a location with weaker gravitational field strength. Explain how its timing changes.', answers: ['Its period increases according to T = 2π√(l/g), so it completes fewer swings and runs slow.', 'Its period decreases because weaker gravity lets the bob move more freely.', 'Its period is unchanged because pendulum period depends only on length.'], correct: 0 }
];
